"""Build a self-contained interactive dashboard from committed aggregate outputs."""
from __future__ import annotations

import csv
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def read_csv(name: str) -> list[dict[str, str]]:
    with (ROOT / "results" / name).open(newline="", encoding="utf-8-sig") as f:
        return list(csv.DictReader(f))


def main() -> None:
    national = json.loads((ROOT / "results/national_op18_gap_summary.json").read_text(encoding="utf-8"))
    periods = read_csv("national_op18_period_summary.csv")
    chosen_starts = {"2018-01-01", "2019-01-01", "2019-10-01", "2021-01-01", "2022-01-01", "2023-01-01", "2024-01-01", "2024-10-01"}
    selected: dict[str, dict[str, str]] = {}
    for row in periods:
        start = row["period_start"]
        if start in chosen_starts and row["period_start"] and row["period_end"]:
            if start not in selected or row["snapshot_date"] > selected[start]["snapshot_date"]:
                selected[start] = row
    trend = sorted(selected.values(), key=lambda r: r["period_end"])
    states = read_csv("state_op18_gap_summary.csv")
    peers = read_csv("peer_group_summary.csv")
    drivers = read_csv("hospital_driver_model_coefficients.csv")
    policy = read_csv("mobile_crisis_event_study.csv")
    hospitals = read_csv("hospital_peer_comparison.csv")
    hospitals = [{k: r.get(k, "") for k in ["facility_id", "facility_name_op18", "state", "psych_gap_minutes", "sample_min_op18bc", "peer_group", "median_gap_minutes", "gap_vs_peer_median_minutes"]} for r in hospitals]
    data = {"national": national, "trend": trend, "states": states, "peers": peers, "drivers": drivers, "policy": policy, "hospitals": hospitals}
    payload = json.dumps(data, ensure_ascii=False, separators=(",", ":")).replace("</", "<\\/")
    html = r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Interactive overview of hospital psychiatric emergency department time, peer differences, and policy analysis."><title>ED mental health wait times dashboard</title><style>
:root{color-scheme:light;--ink:#172a3a;--muted:#526879;--line:#d8e2e8;--paper:#f4f7f8;--panel:#fff;--teal:#147d82;--teal-soft:#dff2f0;--orange:#c66335;--blue:#456c97;--gold:#d3a842;--shade:#edf2f4;font-family:Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif;color:var(--ink);background:var(--paper)}*{box-sizing:border-box}body{margin:0}.shell{max-width:1240px;margin:auto;padding:28px 24px 60px}.top{display:flex;justify-content:space-between;align-items:flex-start;gap:20px;border-bottom:1px solid var(--line);padding-bottom:20px}.eyebrow{font-size:.78rem;letter-spacing:.1em;text-transform:uppercase;color:var(--teal);font-weight:700}h1{font-size:clamp(1.8rem,3vw,2.6rem);line-height:1.1;margin:.4rem 0}.sub{max-width:790px;color:var(--muted);margin:0}.period-tag{white-space:nowrap;color:var(--muted);font-size:.88rem;padding:9px 12px;background:var(--teal-soft);border-radius:99px}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin:22px 0}.metric{padding:18px 20px;background:var(--panel);border:1px solid var(--line);border-radius:12px}.metric label{display:block;color:var(--muted);font-size:.82rem}.metric strong{font-size:1.9rem;display:block;margin:3px 0}.metric span{color:var(--muted);font-size:.8rem}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.panel{background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:18px;min-width:0}.wide{grid-column:1/-1}.panel h2{font-size:1.06rem;margin:0 0 4px}.caption{font-size:.82rem;color:var(--muted);margin:0 0 12px}.chart{width:100%;overflow:hidden}.chart svg{display:block;width:100%;height:auto;overflow:visible}.chart text{font-family:inherit;fill:var(--muted);font-size:11px}.chart .axis{stroke:#b9c8d0;stroke-width:1}.chart .gridline{stroke:#e6edf0;stroke-width:1}.chart .series{stroke:var(--teal);fill:none;stroke-width:3}.chart .dot{fill:var(--teal);stroke:white;stroke-width:2}.chart .bar{fill:var(--teal)}.chart .bar.alt{fill:var(--blue)}.chart .ci{stroke:var(--blue);stroke-width:2}.chart .zero{stroke:var(--orange);stroke-width:1.5;stroke-dasharray:4 4}.controls{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin:8px 0 4px}label.control{font-size:.8rem;color:var(--muted)}select,input{font:inherit;font-size:.9rem;color:var(--ink);background:#fff;border:1px solid #b9c8d0;border-radius:7px;padding:8px 10px;min-height:40px}input{min-width:min(100%,280px)}.tablewrap{overflow:auto;max-height:390px}table{width:100%;border-collapse:collapse;font-size:.86rem}th,td{text-align:left;padding:9px 8px;border-bottom:1px solid var(--line);vertical-align:top}th{position:sticky;top:0;background:#f1f6f7;color:var(--muted);font-size:.75rem;text-transform:uppercase;letter-spacing:.04em}td.num{text-align:right;font-variant-numeric:tabular-nums}.limit{background:#fff6e6;border-left:3px solid var(--gold);padding:10px 13px;color:#574b31;font-size:.83rem;margin:12px 0 0}.footer{color:var(--muted);font-size:.8rem;margin-top:20px}.footer a{color:var(--teal)}.hospital-name{font-weight:600}.muted{color:var(--muted)}@media(max-width:760px){.shell{padding:20px 14px 40px}.grid{grid-template-columns:1fr}.wide{grid-column:auto}.metrics{grid-template-columns:1fr;gap:9px}.metric{padding:13px 16px}.metric strong{font-size:1.55rem}.top{display:block}.period-tag{display:inline-block;margin-top:12px}.panel{padding:14px}}
</style></head><body><main class="shell"><header class="top"><div><div class="eyebrow">CMS hospital data · national view</div><h1>Psychiatric ED time gap</h1><p class="sub">Explore how reported emergency-department times for discharged psychiatric visits compare with the non-psychiatric, non-transfer measure, and how the gap varies across hospitals and years.</p></div><div class="period-tag">Latest period · Oct 2024–Sep 2025</div></header>
<section class="metrics" aria-label="Latest period summary"><div class="metric"><label>Median hospital gap</label><strong id="m-gap"></strong><span>Interquartile range <b id="m-iqr"></b></span></div><div class="metric"><label>Hospitals with both results</label><strong id="m-hospitals"></strong><span id="m-coverage"></span></div><div class="metric"><label>Hospitals with a positive gap</label><strong id="m-positive"></strong><span>Unweighted share among paired hospitals</span></div></section>
<div class="grid"><section class="panel"><h2>How the gap changed</h2><p class="caption">Median hospital gap by selected 12-month reporting period · minutes</p><div class="chart" id="trend" role="img" aria-label="Line chart of median hospital gap across selected reporting periods"></div><p class="limit">Selected windows vary in timing and hospital coverage. This is descriptive and does not identify causes.</p></section>
<section class="panel"><h2>Hospital type and metro peers</h2><p class="caption">Median gap with the 25th–75th percentile range · minutes</p><div class="chart" id="peer" role="img" aria-label="Peer group median gap and interquartile range"></div><p class="limit">Peer groups are descriptive comparisons, not quality scores or adjusted rankings.</p></section>
<section class="panel wide"><h2>State distributions</h2><p class="caption">Unadjusted state medians among hospitals with both results. Sorted to aid comparison; not a state performance ranking.</p><div class="controls"><label class="control" for="state-order">Show</label><select id="state-order"><option value="high">Higher median gaps</option><option value="low">Lower median gaps</option></select><label class="control" for="state-search">Find state</label><input id="state-search" type="search" placeholder="State abbreviation"></div><div class="chart" id="states" role="img" aria-label="Bar chart of state median hospital gaps"></div><div id="state-table" class="tablewrap"></div></section>
<section class="panel wide"><h2>Hospital characteristics</h2><p class="caption">Adjusted cross-sectional associations with the latest hospital gap · minutes, state fixed effects and state-clustered intervals</p><div class="chart" id="drivers" role="img" aria-label="Coefficient plot with 95 percent intervals for hospital characteristics"></div><p class="limit">These are exploratory associations, not causal effects. The outcome is a difference between separately reported medians, and the model explains about 5.7% of gap variation.</p></section>
<section class="panel wide"><h2>Medicaid mobile-crisis authorization</h2><p class="caption">Exploratory group-time ATT by years since the first fully treated annual window · minutes</p><div class="chart" id="policy" role="img" aria-label="Event study estimates and state-cluster bootstrap intervals"></div><p class="limit">Treatment is SPA effective-date authorization, not verified statewide team availability. The event-time 0 estimate is +3.1 minutes (95% interval −9.3 to +15.8); this does not establish no effect. Early cohorts are small and later follow-up is short.</p></section>
<section class="panel wide"><h2>Find a hospital</h2><p class="caption">Search latest-period values and compare each hospital with its predefined peer group.</p><div class="controls"><input id="hospital-search" type="search" placeholder="Hospital name or CMS ID"><select id="hospital-state"><option value="">All states</option></select><select id="hospital-peer"><option value="">All peer groups</option></select></div><div id="hospital-count" class="caption" aria-live="polite"></div><div id="hospital-table" class="tablewrap"></div><p class="limit">The displayed difference is not an individual patient's extra waiting time. The CMS sample field is not used here to construct confidence intervals.</p></section></div>
<footer class="footer">Sources: <a href="https://data.cms.gov/provider-data/dataset/yv7e-xc69">CMS Timely and Effective Care</a>, <a href="https://data.cms.gov/provider-data/dataset/xubh-q36u">CMS Hospital General Information</a>, and <a href="https://www.ers.usda.gov/data-products/rural-urban-continuum-codes/">USDA 2023 RUCC</a>. OP-18 measures discharged ED visits, not admitted-patient boarding. Missing or suppressed scores are excluded. <br><br><a href="../results/executive_brief.md">Executive brief</a> · <a href="../results/national_historical_benchmark.md">Historical benchmark</a> · <a href="../results/hospital_driver_analysis.md">Driver analysis</a> · <a href="../results/mobile_crisis_policy_analysis.md">Policy methods</a></footer></main>
<script>const D=__DATA__;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const num=x=>Number(x);const fmt=x=>Math.round(num(x)).toLocaleString();const svg=(w,h,contents,label)=>`<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(label)}"><title>${esc(label)}</title>${contents}</svg>`;
const N=D.national;document.getElementById('m-gap').textContent=fmt(N.median_gap_minutes)+' min';document.getElementById('m-iqr').textContent=`${fmt(N.gap_p25_minutes)}–${fmt(N.gap_p75_minutes)} min`;document.getElementById('m-hospitals').textContent=fmt(N.rows_with_op18b_and_op18c);document.getElementById('m-coverage').textContent=`${(100*N.gap_available_share).toFixed(1)}% of ${fmt(N.op18_hospital_period_rows)} hospitals in the extract`;document.getElementById('m-positive').textContent=`${(100*N.positive_gap_rows/N.rows_with_op18b_and_op18c).toFixed(1)}%`;
function drawTrend(){const rows=D.trend,w=760,h=270,L=54,R=18,T=18,B=48,iw=w-L-R,ih=h-T-B,max=120,x=i=>L+i*iw/(rows.length-1),y=v=>T+ih*(1-num(v)/max);let c='';[0,30,60,90,120].forEach(v=>{c+=`<line class="gridline" x1="${L}" y1="${y(v)}" x2="${w-R}" y2="${y(v)}"/><text x="${L-9}" y="${y(v)+4}" text-anchor="end">${v}</text>`});c+=`<line class="axis" x1="${L}" y1="${T+ih}" x2="${w-R}" y2="${T+ih}"/><text x="${L}" y="${h-7}">Reporting period</text><text transform="translate(14 ${T+ih/2}) rotate(-90)" text-anchor="middle">Median gap (minutes)</text>`;const pts=rows.map((r,i)=>`${x(i)},${y(r.median_gap_minutes)}`).join(' ');c+=`<polyline class="series" points="${pts}"/>`;rows.forEach((r,i)=>{const year=r.period_end.slice(0,4);c+=`<circle class="dot" cx="${x(i)}" cy="${y(r.median_gap_minutes)}" r="5" tabindex="0"><title>${esc(r.period_start)} to ${esc(r.period_end)}: ${fmt(r.median_gap_minutes)} minutes, ${fmt(r.hospitals_with_both_measures)} hospitals</title></circle><text x="${x(i)}" y="${T+ih+20}" text-anchor="middle">${year}</text>`});document.getElementById('trend').innerHTML=svg(w,h,c,'Median psychiatric ED time gap across selected annual reporting periods');}
function drawPeers(){const rows=D.peers.filter(r=>r.peer_group_meets_minimum==='True'),w=760,h=Math.max(240,rows.length*43+65),L=260,R=55,T=20,B=35,iw=w-L-R,max=200,x=v=>L+num(v)/max*iw;let c='';[0,50,100,150,200].forEach(v=>{c+=`<line class="gridline" x1="${x(v)}" y1="${T}" x2="${x(v)}" y2="${h-B}"/><text x="${x(v)}" y="${h-8}" text-anchor="middle">${v}</text>`});c+=`<text x="${L+iw/2}" y="${h-1}" text-anchor="middle">Gap (minutes)</text>`;rows.forEach((r,i)=>{const yy=T+i*43+19,a=x(r.gap_p25_minutes),b=x(r.gap_p75_minutes),m=x(r.median_gap_minutes);c+=`<text x="${L-10}" y="${yy+4}" text-anchor="end">${esc(r.peer_group)}</text><line class="ci" x1="${a}" y1="${yy}" x2="${b}" y2="${yy}"/><circle class="dot" cx="${m}" cy="${yy}" r="6"><title>${esc(r.peer_group)}: median ${fmt(r.median_gap_minutes)} min; IQR ${fmt(r.gap_p25_minutes)}–${fmt(r.gap_p75_minutes)}; n=${fmt(r.hospitals)}</title></circle><text x="${Math.min(m+10,w-R-25)}" y="${yy+4}">${fmt(r.median_gap_minutes)}</text>`});document.getElementById('peer').innerHTML=svg(w,h,c,'Peer-group median gaps and interquartile ranges');}
function drawStates(){let rows=D.states.filter(r=>!document.getElementById('state-search').value||r.state.toLowerCase().includes(document.getElementById('state-search').value.toLowerCase()));rows.sort((a,b)=>num(a.median_gap_minutes)-num(b.median_gap_minutes));if(document.getElementById('state-order').value==='high')rows.reverse();rows=rows.slice(0,12);const w=920,h=340,L=56,R=25,T=15,B=60,iw=w-L-R,ih=h-T-B,max=200,slot=ih/rows.length,bw=Math.min(34,slot*.62),x=v=>L+num(v)/max*iw;let c='';[0,50,100,150,200].forEach(v=>{c+=`<line class="gridline" x1="${x(v)}" y1="${T}" x2="${x(v)}" y2="${h-B}"/><text x="${x(v)}" y="${h-34}" text-anchor="middle">${v}</text>`});rows.forEach((r,i)=>{const yy=T+i*slot+(slot-bw)/2;c+=`<rect class="bar alt" x="${L}" y="${yy}" width="${Math.max(0,x(r.median_gap_minutes)-L)}" height="${bw}" rx="3"><title>${r.state}: median ${fmt(r.median_gap_minutes)} minutes across ${fmt(r.hospitals_with_both_measures)} hospitals</title></rect><text x="${L-8}" y="${yy+bw/2+4}" text-anchor="end">${esc(r.state)}</text><text x="${x(r.median_gap_minutes)+6}" y="${yy+bw/2+4}">${fmt(r.median_gap_minutes)}</text>`});c+=`<text x="${L+iw/2}" y="${h-7}" text-anchor="middle">Median hospital gap (minutes)</text>`;document.getElementById('states').innerHTML=rows.length?svg(w,h,c,'State medians, sorted for comparison; not rankings'):'';document.getElementById('state-table').innerHTML=`<table><thead><tr><th>State</th><th>Hospitals</th><th>Median gap</th><th>Mean gap</th><th>Positive gap share</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.state)}</td><td>${fmt(r.hospitals_with_both_measures)}</td><td>${fmt(r.median_gap_minutes)} min</td><td>${num(r.mean_gap_minutes).toFixed(1)} min</td><td>${(100*num(r.positive_gap_share)).toFixed(1)}%</td></tr>`).join('')}</tbody></table>`;}
function drawDrivers(){const keep=['emergency_services[Yes]','hospital_type[Critical Access Hospitals]','rurality[Nonmetro]','hospital_ownership[Physician]','hospital_ownership[Government - Hospital District or Authority]'];const rows=D.drivers.filter(r=>keep.includes(r.term)),w=900,h=300,L=370,R=95,T=20,B=42,iw=w-L-R,lo=-160,hi=120,x=v=>L+(num(v)-lo)/(hi-lo)*iw,slot=(h-T-B)/rows.length;let c='';[-150,-100,-50,0,50,100].forEach(v=>{c+=`<line class="${v===0?'zero':'gridline'}" x1="${x(v)}" y1="${T}" x2="${x(v)}" y2="${h-B}"/><text x="${x(v)}" y="${h-16}" text-anchor="middle">${v}</text>`});rows.forEach((r,i)=>{const yy=T+i*slot+slot/2,est=num(r.estimate_minutes),a=x(r.ci95_low),b=x(r.ci95_high),m=x(est),lab=r.term.replace('hospital_ownership[','').replace('hospital_type[','').replace('rurality[','').replace('emergency_services[','').replace(']','');c+=`<text x="${L-12}" y="${yy+4}" text-anchor="end">${esc(lab)}</text><line class="ci" x1="${a}" y1="${yy}" x2="${b}" y2="${yy}"/><circle class="dot" cx="${m}" cy="${yy}" r="5"><title>${esc(lab)}: ${est.toFixed(1)} minutes; 95% interval ${num(r.ci95_low).toFixed(1)} to ${num(r.ci95_high).toFixed(1)}</title></circle><text x="${w-R+8}" y="${yy+4}">${est>0?'+':''}${est.toFixed(1)}</text>`});c+=`<text x="${L+iw/2}" y="${h-1}" text-anchor="middle">Adjusted association with gap (minutes)</text>`;document.getElementById('drivers').innerHTML=svg(w,h,c,'Selected adjusted hospital characteristic associations with 95 percent intervals');}
function drawPolicy(){const rows=D.policy,w=760,h=260,L=70,R=35,T=18,B=45,iw=w-L-R,ih=h-T-B,lo=-90,hi=50,x=v=>L+(num(v)-lo)/(hi-lo)*iw,y=i=>T+i*ih/(rows.length-1);let c='';[-80,-40,0,40].forEach(v=>{const xx=x(v);c+=`<line class="${v===0?'zero':'gridline'}" x1="${xx}" y1="${T}" x2="${xx}" y2="${h-B}"/><text x="${xx}" y="${h-18}" text-anchor="middle">${v}</text>`});rows.forEach((r,i)=>{const yy=y(i),a=x(r.ci95_low),b=x(r.ci95_high),m=x(r.att_minutes);c+=`<text x="${L-12}" y="${yy+4}" text-anchor="end">Event time ${r.event_time}</text><line class="ci" x1="${a}" y1="${yy}" x2="${b}" y2="${yy}"/><circle class="dot" cx="${m}" cy="${yy}" r="5"><title>Event time ${r.event_time}: ${num(r.att_minutes).toFixed(1)} minutes; state-cluster bootstrap interval ${num(r.ci95_low).toFixed(1)} to ${num(r.ci95_high).toFixed(1)}</title></circle><text x="${Math.min(m+10,w-R-20)}" y="${yy-8}">${num(r.att_minutes)>0?'+':''}${num(r.att_minutes).toFixed(1)}</text>`});c+=`<text x="${L+iw/2}" y="${h-1}" text-anchor="middle">ATT (minutes; 95% state-cluster bootstrap interval)</text>`;document.getElementById('policy').innerHTML=svg(w,h,c,'Mobile-crisis SPA authorization event-time estimates and intervals');}
function drawHospital(){const q=document.getElementById('hospital-search').value.trim().toLowerCase(),s=document.getElementById('hospital-state').value,p=document.getElementById('hospital-peer').value;const list=D.hospitals.filter(r=>(!s||r.state===s)&&(!p||r.peer_group===p)&&(!q||`${r.facility_name_op18} ${r.facility_id}`.toLowerCase().includes(q))).sort((a,b)=>a.facility_name_op18.localeCompare(b.facility_name_op18));document.getElementById('hospital-count').textContent=`${list.length.toLocaleString()} hospitals with paired results`;document.getElementById('hospital-table').innerHTML=`<table><thead><tr><th>Hospital</th><th>State</th><th>Peer group</th><th>Hospital gap</th><th>Peer median</th><th>Difference</th><th>Sample (minimum)</th></tr></thead><tbody>${list.slice(0,100).map(r=>`<tr><td><span class="hospital-name">${esc(r.facility_name_op18)}</span><br><span class="muted">CMS ${esc(r.facility_id)}</span></td><td>${esc(r.state)}</td><td>${esc(r.peer_group||'Unknown')}</td><td class="num">${fmt(r.psych_gap_minutes)} min</td><td class="num">${r.median_gap_minutes?fmt(r.median_gap_minutes)+' min':'—'}</td><td class="num">${r.gap_vs_peer_median_minutes?fmt(r.gap_vs_peer_median_minutes)+' min':'—'}</td><td class="num">${esc(r.sample_min_op18bc)}</td></tr>`).join('')||'<tr><td colspan="7">No hospitals match.</td></tr>'}</tbody></table>`;if(list.length>100)document.getElementById('hospital-count').textContent+=` · showing first 100; narrow the search to see more`}
drawTrend();drawPeers();drawStates();drawDrivers();drawPolicy();const add=(id,items)=>{const el=document.getElementById(id);[...new Set(items)].filter(Boolean).sort().forEach(v=>{const o=document.createElement('option');o.value=v;o.textContent=v;el.append(o)})};add('hospital-state',D.hospitals.map(x=>x.state));add('hospital-peer',D.hospitals.map(x=>x.peer_group));document.getElementById('state-order').addEventListener('change',drawStates);document.getElementById('state-search').addEventListener('input',drawStates);['hospital-search','hospital-state','hospital-peer'].forEach(id=>document.getElementById(id).addEventListener('input',drawHospital));drawHospital();
</script></body></html>'''.replace("__DATA__", payload)
    target = ROOT / "site" / "dashboard.html"
    target.write_text(html, encoding="utf-8")
    print(f"Wrote {target} ({target.stat().st_size:,} bytes; {len(states)} state summaries; {len(trend)} selected time points)")


if __name__ == "__main__":
    main()

